// runs inside a tower Layer's Service::call, after poll_ready succeeds:
async fn guard<S, B>(rule: &Rule, mut req: Request<B>, inner: &mut S) -> Result<S::Response, Error>
where S: Service<Request<B>, Error = Error> {
    let id = verify(&req)?;                       // this gate's own evidence
    if !rule.allows(&id, &req) {                  // fail closed
        return Err(Error::Denied);
    }
    req.extensions_mut().insert(id);              // typed identity travels inward
    inner.call(req).await                         // delegate to the inner layer
}
// composition: the edge gate layer wraps the tenant gate layer around the inner service
